const LEGAL = {"_lisez_moi":"Source unique des mentions légales (pages de site/, pieds de page de site/ et de espace/web/, pieds légaux des emails du moteur et de n8n). Une valeur encore à compléter commence par l'un des marqueurs de outils/legal.py (MARQUES) et s'affiche en gras sur les pages. Après toute modification : python3 outils/legal.py (réécrit les pages), puis python3 n8n/build_automatisations.py, build_maj_membre.py, build_ordre10.py, build_audit.py et python3 moteur/avis/build_workflow.py (régénèrent les emails). Le test moteur/tests/test_legal.py refuse toute page en retard sur ce fichier.","nom_commercial":"BoostImpact","societe":{"denomination":"Girlden LTD","forme":"société à responsabilité limitée de droit anglais (private limited company)","numero":"14837617","registre":"Companies House","pays_immatriculation":"Angleterre et au pays de Galles","siege":"71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni","capital":"1 GBP (déclaration de capital à l'immatriculation, Companies House, 1er mai 2023)","tva":"Non assujettie à la TVA (prestataire non établi dans l'Union européenne ; autoliquidation par le Client)"},"directeur_publication":"Pierre-Jean Deàk Grisoni","contact":{"email":"info@boostimpact.agency","telephone":"sur demande, par email"},"site_url":"https://boostimpact.agency","hebergement":{"pages_production":"cloudflare_pages","fournisseurs":{"cloudflare_pages":{"nom":"Cloudflare, Inc. (service Cloudflare Pages)","adresse":"101 Townsend St., San Francisco, CA 94107, États-Unis","telephone":"+1 650 319 8930","source":"https://www.cloudflare.com/en/website-terms/ (lue le 25/10/2026)"},"supabase":{"nom":"Supabase Pte. Ltd.","adresse":"65 Chulia Street #38-02/03, OCBC Centre, Singapour 049513","telephone":"non publié (contact : legal@supabase.com)","source":"https://supabase.com/terms (lue le 13/10/2026, adresse présentée comme « place of business »)"}}},"documents":{"version":"17 novembre 2026, version 3"},"facturation":{"premier_mois":"le premier mois, ou la première année en paiement annuel, est facturé en entier le jour de la souscription, sans calcul au prorata ; l'abonnement se renouvelle ensuite de date à date, chaque mois ou chaque année selon le rythme de paiement choisi","moyen_paiement":"carte bancaire, par Stripe","taux_penalites":"taux de refinancement le plus récent de la Banque centrale européenne, majoré de 10 points"},"frais_mise_en_route":{"actif":true,"montant_ht":"190","offerts_paiement":"annuel","offres":["standard","premium"],"offerts_apres_option":"visibilite_ia"},"droit_applicable":"pays_client","fournisseur_email":"Google Workspace (Google Ireland Limited, Gordon House, Barrow Street, Dublin 4, Irlande)","pied_email":"{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}."};
// Anglais et néerlandais : même phrase que pied_texte_en et pied_texte_nl d'outils/legal.py (TRADUCTIONS, TRADUCTIONS_NL), avec la valeur française
// qu'elles traduisent. Si legal.json a changé sans que la traduction suive, le pied reste en français (jamais une valeur fausse) ; le test
// moteur/tests/test_courriels_langues.js compare ces phrases à celles d'outils/legal.py.
const PIED_FR = "{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}.";
const PIED_LANGUES = {
  en: { gabarit: "{nom_commercial} is a trading name of {denomination}, a company registered in {pays_immatriculation} ({registre}) under number {numero}. Registered office: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "England and Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, United Kingdom"] }, confidentialite: "Privacy: ", page: "/en/privacy.html" },
  nl: { gabarit: "{nom_commercial} is een handelsnaam van {denomination}, een vennootschap ingeschreven in {pays_immatriculation} ({registre}) onder nummer {numero}. Zetel: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "Engeland en Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Verenigd Koninkrijk"] }, confidentialite: "Privacy: ", page: "/nl/privacy.html" },
};
// Langue du pied : celle demandée si sa traduction est à jour de legal.json, sinon le français.
function langueDuPied(lg) {
  const t = PIED_LANGUES[langueEmail(lg)], s = LEGAL.societe;
  return t && LEGAL.pied_email === PIED_FR && Object.entries(t.valeurs).every(([k, [fr]]) => s[k] === fr) ? langueEmail(lg) : "fr";
}
function piedLegalTexte(lg) {
  const s = LEGAL.societe, p = langueDuPied(lg);
  if (p === "fr") return LEGAL.pied_email.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : s[k]);
  const t = PIED_LANGUES[p];
  return t.gabarit.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : t.valeurs[k] ? t.valeurs[k][1] : s[k]);
}
function lienConfidentialite(lg) {
  const u = String(LEGAL.site_url || "").replace(/\/+$/, ""), p = langueDuPied(lg);
  return /^https:\/\/[^\s"<>]+$/.test(u) ? u + (p === "fr" ? "/confidentialite.html" : PIED_LANGUES[p].page) : null;
}
const libelleConfidentialite = lg => langueDuPied(lg) === "fr" ? "Confidentialité : " : PIED_LANGUES[langueDuPied(lg)].confidentialite;
function piedLegalHtml(lg) { const u = lienConfidentialite(lg); return `${echapper(piedLegalTexte(lg))} ${libelleConfidentialite(lg)}${u ? lien(u, u) : "<strong>A_FOURNIR</strong>"}.`; }
const avecPied = (texte, lg) => texte + "\n\n" + piedLegalTexte(lg) + "\n" + libelleConfidentialite(lg) + (lienConfidentialite(lg) || "A_FOURNIR") + ".";

function page(titre, blocs, pied, lg) {
