  const resto = /restaurant|restauration/i.test(String(d.metier || el.metier || "")), quoiC = { fr: resto ? "votre restaurant" : "votre commerce", en: resto ? "your restaurant" : "your business", nl: resto ? "uw restaurant" : "uw zaak" }[lg];
  const plus = d.offre_id === "essentiel" && (d.offre_suivante_id === "standard" || d.offre_suivante_id === "premium") ? T.plusEssentiel(quoiC) : "";
  const p2 = T.comprend(suivante, total, videos) + (plus ? " " + plus : "") + (prix ? "\n" + prix : "");
