function offreSuperieureEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_OFFRE[lg], C = COMMUN[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const nom = nettoyerNom(el.commerce), d = el.detail || {}, url = adresse(ctx.urlEspace, "/#/offre?dessus");
  const mois = MOIS_LANGUE[lg][+new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Paris", month: "2-digit" }).format(ctx.maintenant || new Date()) % 12];   // mois suivant, heure de Paris
  if (!d.offre || !d.offre_suivante || !(+d.plafond > 0) || !(+d.publications_suivante > 0)) throw new Error("offre incomplète");
  const sujet = T.sujet;
  const p1 = T.utilise(nom, d.plafond, nomOffre(d.offre_id, lg, d.offre), mois);
  const total = +d.publications_suivante + (+d.videos_suivante || 0), videos = +d.videos_suivante > 0 ? d.videos_suivante : 0, suivante = nomOffre(d.offre_suivante_id, lg, d.offre_suivante);
  const px = PRIX_OFFRES[d.offre_suivante_id], prix = px ? T.prix(px.annuel, px.mensuel) : null;
  // Lot 6a (15/11/2026, copywriter) : depuis l'Essentiel, l'argument principal de l'offre du dessus : les réseaux sociaux, et la Visibilité IA offerte à
  // l'année (moteur/options.json, inclus_annuel : standard et premium ; 490 € HT sinon).
  // Lot 8 (copywriter, tour 6) : « votre restaurant » quand le métier est connu comme restaurant (detail.metier ou el.metier), sinon « votre commerce » ;
  // le prix sur sa propre ligne dans la version texte (le HTML le met déjà à part dans l'encart).
  const resto = /restaurant|restauration/i.test(String(d.metier || el.metier || "")), quoiC = { fr: resto ? "votre restaurant" : "votre commerce", en: resto ? "your restaurant" : "your business", nl: resto ? "uw restaurant" : "uw zaak" }[lg];
  const plus = d.offre_id === "essentiel" && (d.offre_suivante_id === "standard" || d.offre_suivante_id === "premium") ? T.plusEssentiel(quoiC) : "";
  const p2 = T.comprend(suivante, total, videos) + (plus ? " " + plus : "") + (prix ? "\n" + prix : "");
  // Montée depuis l'Essentiel (CGV art. 4, legal:frais) : 190 € HT de mise en route en paiement mensuel, offerts à l'année ou après la Visibilité IA.
  const changer = T.changer(suivante) + (d.offre_id === "essentiel" ? " " + T.fraisEssentiel : "");
