const FORMULE_CHER = /^\s*(cher|chere|chers|cheres|monsieur|madame|mesdames|messieurs)\b/;
// Reponse d'un commerce neerlandophone (fiche.langue = "nl", commerces.langue) : redigee en neerlandais, vouvoiement = « u » / « uw ».
// Memes libelles de refus qu'en francais (l'espace les traduit). Les mots francais restent interdits aussi (commerce belge bilingue).
const NL = {
  INTERDITES: [
    ["fait maison", /\b(huisgemaakt\w*|zelfgemaakt\w*|eigen makelij)\b/], ["frais", /\b(vers|verse|versheid|dagvers\w*)\b/], ["bio", /\b(biologisch\w*|bio)\b/],
    ["artisanal", /\bambachtelijk\w*|\bartisanaal\w*/], ["local", /\b(lokaal|lokale|streek\w*|producent\w*|uit de buurt|van bij ons)\b/],
    ["origine", /\b(belgisch\w*|vlaams\w*|herkomst|afkomstig)\b/], ["prix", /\bprijs\w*|\btarie\w*|\d\s?(€|euro)/], ["allergene", /allergen\w*|\bgluten\w*|\blactose\w*/],
  ],
  GESTES: /\b(gratis|korting|terugbetal\w*|vergoed\w*|tegoedbon|cadeaubon|cadeau|aangeboden|trakteren|op kosten van het huis)\b/,
  PROMESSES: /\b(beloven|beloof\w*|belofte|garanderen|garandeer\w*|gegarandeerd|garantie|verbinden ons|voortaan|in de toekomst|nooit meer|vanaf nu)\b/,
  MACHINE: /\b(ai|ki|kunstmatige intelligentie|artificiele intelligentie|robot|geautomatiseerd\w*|automatisch\w*|geschreven door|gegenereerd|chatbot|virtuele assistent|door een mens)\b/,
  DISPUTE: /\b(kwade trouw|ongelijk|onwaar|leugen\w*|overdreven|overdrijv\w*|betwisten|betwist|klopt niet|niet waar|onjuist|belachelijk)\b/,
  ACCUSE: /\b(spijt|spijtig|jammer|sorry|excuses|excuseer|verontschuldig\w*|teleurgesteld\w*|teleurstell\w*|vervelend\w*)\b/,
  TUTOIEMENT: /\b(je|jij|jou|jouw|jullie)\b/,
  VOUVOIEMENT: /\b(u|uw)\b/,
  FORMULE_CHER: /^\s*(geachte|meneer|mevrouw|heer)\b/,
};

// Lot 8 (rapport d'expert) : jamais d'action affirmée que le restaurateur n'a pas confirmée (« nous avons revu l'organisation », « nous en parlons
// en cuisine ») : refusée sauf si la précision du commerçant (avis.precision, fiche.precision_commercant) existe. « Je transmets votre message »
// (remerciement sur un avis positif) reste permis.
const ACTIONS = /\b(nous avons (revu|change|modifie|reorganise|parle|transmis|pris des mesures|ameliore|corrige|forme|rappele)|nous en (parlons|avons parle|discutons)|j'en ai parle|je l'ai (dit|transmis|signale)|nous allons (revoir|changer|ameliorer|reorganiser)|en cuisine,? nous)\b/;
const ACTIONS_NL = /\b(we hebben (het |dit )?(besproken|aangepast|veranderd|doorgegeven|verbeterd)|ik heb het (besproken|doorgegeven)|we bespreken (het|dit)|we gaan (het|dit) (aanpassen|veranderen|verbeteren))\b/;
const ACTIONS_EN = /\b(we (have|'ve) (reviewed|changed|spoken|talked|passed|raised|addressed|fixed)|i (have|'ve) (spoken|talked|raised|passed)|we are (discussing|looking into|reviewing)|we're (discussing|looking into|reviewing)|we will (change|review|improve))\b/;
// Anglais (avis écrit en anglais : réponse en anglais) : promesses et gestes.
const EN = { PROMESSES: /\b(from now on|never again|we guarantee|we promise|going forward)\b/, GESTES: /\b(free|discount|refund\w*|on the house|voucher|complimentary)\b/,
  DISPUTE: /\b(bad faith|untrue|not true|lie|lies|lying|exaggerat\w*|ridiculous|fake)\b/, ACCUSE: /\b(sorry|apologi\w*|regret\w*|shame|disappoint\w*|unfortunate\w*)\b/ };
// Langue d'un texte (heuristique sur les mots courants) : "fr", "nl", "en" ou null (trop court ou mélangé).
function langueTexte(texte) {
  const m = sansAccents(texte || "").match(/[a-z']+/g) || [];
  const c = (l) => m.filter(w => l.includes(w)).length;
  const fr = c(["le","la","les","et","est","une","des","pour","pas","tres","avec","nous","vous","mais","du","au","c'est","j'ai","merci","bon","bonne"]);
  const nl = c(["de","het","een","en","is","niet","met","voor","zeer","heel","maar","wij","u","uw","lekker","goed","was","van","ik","bedankt","dank"]);
  const en = c(["the","and","is","was","very","with","for","not","but","we","you","your","great","good","food","service","staff","really","thank","thanks","i","it",
    "fresh","attentive","delicious","lovely","friendly","amazing","nice","meal","dish","place","recommend","my","our","of","to","so","had"]);   // lot 8 : avis anglais courts
  const max = Math.max(fr, nl, en); if (max < 2) return null;
  return [["fr", fr], ["nl", nl], ["en", en]].filter(([, n]) => n === max).length > 1 ? null : [["fr", fr], ["nl", nl], ["en", en]].find(([, n]) => n === max)[0];
}
// Prénom utilisable (lot 8, rapport d'expert D11) : le premier mot du nom affiché seulement s'il ressemble à un prénom ; sinon null (pseudonyme,
// nom de lieu, chiffres) : la réponse commence alors par « Bonjour, » sans nom, et le contrôle n'exige aucun prénom.
const PAS_PRENOM = ["le","la","les","l","restaurant","resto","cafe","hotel","bar","brasserie","bistrot","mr","mme","m","mlle","the","de","het","een","un","une","google","utilisateur","user","a","famille","family","team","equipe"];
function prenomDe(nom) {
  const m = String(nom || "").trim().split(/\s+/).filter(Boolean); if (!m.length) return null;
  const p = m[0].replace(/[.,;:!?]+$/, "");
  if (/\d/.test(p) || Array.from(p).filter(ch => /\p{L}/u.test(ch)).length < 2 || !/^\p{Lu}/u.test(p) || PAS_PRENOM.includes(sansAccents(p))) return null;
  return p;
}
const derniere = r => { const p = String(r || "").trim().split(/(?<=[.!?])\s+/).filter(x => x.trim()); return p.length ? p[p.length - 1] : ""; };
const sansSignature = (r, sig) => { const x = String(r || "").trim(); const g = String(sig || "").trim(); return g && x.endsWith(g) ? x.slice(0, -g.length).trim() : x; };

// avis : {note, prenom, texte, vide, precision}; fiche : {contact, motsCles[], mentionsAutorisees[], gestes, mots_signature[], a_eviter[]}; precedentes : reponses deja rendues dans la serie
function controle(reponse, avis, fiche, precedentes = []) {
  const refus = []; const t = sansAccents(reponse); const f = Object.assign({}, fiche || {}); const lr = langueTexte(reponse);
  // Lot 8 : réponse dans la langue de l'AVIS (anglais ou néerlandais acceptés seulement si l'avis l'est), sinon dans celle du commerce.
  const la = langueTexte((avis && avis.texte) || ""); const en = lr === "en" && (la === "en" || la === null); /* lot 8 : avis trop court pour dire sa langue, réponse anglaise jugée en anglais */ const nl = !en && (f.langue === "nl" || (lr === "nl" && la === "nl"));
  f.motsCles = f.motsCles || f.mots_cles || []; f.mentionsAutorisees = f.mentionsAutorisees || f.mentions_autorisees || [];
  // Expressions maison du kit de marque : ecrites par le commercant lui-meme, elles comptent comme autorisees (meme regle que le moteur).
  const autorise = sansAccents((f.mentionsAutorisees || []).join(" ") + " " + (f.specialites || "") + " " + (f.mots_signature || []).join(" "));
  if (/--|—|–/.test(reponse)) refus.push("tiret double ou long");
  // Lot 8 : réponse en anglais (avis écrit en anglais) : pas de vouvoiement à exiger, règles anglaises en plus.
  if (!en && (nl ? NL.TUTOIEMENT : TUTOIEMENT).test(t)) refus.push("tutoiement");   // « te » est un mot neerlandais courant (« te verwelkomen »)
  if (!en && !(nl ? NL.VOUVOIEMENT : /\b(vous|votre|vos)\b/).test(t)) refus.push("pas de vouvoiement");
  if (en && /^\s*dear (sir|madam)/i.test(reponse)) refus.push("formule Cher/Monsieur/Madame");
  if (FORMULE_CHER.test(t) || (nl && NL.FORMULE_CHER.test(t))) refus.push("formule Cher/Monsieur/Madame");
  if (avis.prenom && !sansAccents(reponse).includes(sansAccents(avis.prenom))) refus.push("prenom absent");
  const phrases = sansSignature(reponse, f.signature).split(/(?<=[.!?])\s+/).filter(s => s.trim());
  const minP = avis.vide || Number(avis.note) === 5 ? 1 : 2;   // lot 8 : 5 étoiles ou avis sans texte, une phrase suffit
  if (phrases.length < minP || phrases.length > 5) refus.push("longueur : " + phrases.length + " phrases (" + minP + " a 5 attendues)");
  if (reponse.length > 650) refus.push("trop long (" + reponse.length + " signes)");
  const vus = new Set();
  for (const [nom, re] of INTERDITES.concat(nl ? NL.INTERDITES : [])) if (re.test(t) && !re.test(autorise) && !vus.has(nom)) { vus.add(nom); refus.push("mention non ecrite par le client : " + nom); }
  if ((GESTES.test(t) || (nl && NL.GESTES.test(t)) || (en && EN.GESTES.test(t))) && !f.gestes) refus.push("geste commercial non prevu par la fiche");
  if (PROMESSES.test(t) || (nl && NL.PROMESSES.test(t)) || (en && EN.PROMESSES.test(t))) refus.push("promesse");
  const precision = String((avis && avis.precision) || f.precision_commercant || "").trim();
  if (!precision && (ACTIONS.test(t) || ACTIONS_NL.test(t) || ACTIONS_EN.test(t))) refus.push("action non confirmee par le commercant");
  if (MACHINE.test(t) || (nl && NL.MACHINE.test(t))) refus.push("mention de redaction automatique");
  if (DISPUTE.test(t) || (nl && NL.DISPUTE.test(t)) || (en && EN.DISPUTE.test(t))) refus.push("dispute");
  for (const x of fautesMarque(reponse, f.a_eviter)) refus.push("expression a eviter (kit de marque) : " + x);
  // Google n'offre aucune messagerie privee sur les avis (remarque de PJ, 23/10/2026) : jamais « en prive », « message prive », « MP ».
  if (/\b(en prive|message prive|messages prives|messagerie|par mp|en mp|message direct)\b/.test(t) || (nl && /\b(prive|priveberich\w*|persoonlijk bericht|dm)\b/.test(t))) refus.push("contact impossible sur Google (pas de message prive)");
  if (/[\w.+-]+@[\w-]+\.[\w.]+|\d[\d .]{7,}\d/.test(reponse) && !(f.contact && reponse.includes(f.contact))) refus.push("donnee personnelle");
  if (avis.note <= 3) {
    if (!ACCUSE.test(t) && !(nl && NL.ACCUSE.test(t)) && !(en && EN.ACCUSE.test(t))) refus.push("avis negatif : aucune reconnaissance du vecu");
    // Lot 8 (rapport d'expert, ses exemples C1 et C4) : le contact n'est exigé que pour 1 étoile ; de 2 à 3 étoiles il est permis, pas exigé
    // (un plat tiède n'appelle pas de numéro) ; à partir de 4 étoiles il est refusé (plus bas).
    if (Number(avis.note) <= 1 && f.contact && !reponse.includes(f.contact)) refus.push("avis negatif : contact de la fiche absent");
  } else if (f.contact && reponse.includes(f.contact)) refus.push("contact inutile sur un avis positif");
  // Lot 8 : plus de bourrage de mots-clés : un mot-clé de la fiche n'est permis que si le client l'a lui-même écrit.
  const tav = sansAccents((avis && avis.texte) || "");
  for (const k of f.motsCles || []) { const kk = sansAccents(k); if (kk && t.includes(kk) && !tav.includes(kk)) refus.push("mot-cle ajoute : " + k); }
  // Anti-répétition (lot 8) : comparée aux 10 dernières réponses du commerce, sur le début (3 premiers mots) ET la dernière phrase (hors signature).
  const dix = (precedentes || []).filter(Boolean).slice(-10);
  const debut = t.split(/\s+/).slice(0, 3).join(" "), fin = sansAccents(derniere(sansSignature(reponse, f.signature))).replace(/\s+/g, " ").trim();
  if (dix.some(p => sansAccents(p).split(/\s+/).slice(0, 3).join(" ") === debut)) refus.push("meme debut que les reponses precedentes");
  if (fin && dix.some(p => sansAccents(derniere(sansSignature(p, f.signature))).replace(/\s+/g, " ").trim() === fin)) refus.push("meme fin que les reponses precedentes");
  return refus;
}

// Decision d'envoi selon l'OFFRE du commerce (regle unique de publication, 16/10/2026 ; moteur/offres.json : avis_auto, avis_equipe, delegation) :
//   avis sensible (detection par le CONTENU, quelle que soit la note) : "humain", jamais publie automatiquement ;
//   Standard et Premium (avis_auto) : 4 et 5 etoiles conformes aux regles -> "publication_automatique" ;
//   Standard et Premium (avis_equipe, decision de PJ du 22/10/2026) : tout le reste -> "equipe" (l'equipe BoostImpact relit, publie sous 24 h
//   et PREVIENT le commercant, sans lui demander son accord : mandat de publication, CGV article 8) ; delegation (Premium) garde le meme effet ;
//   Essentiel : tout le reste -> "validation_commercant" (rien n'est publie sans le client).
// Offre inconnue ou absente : aucune publication automatique (le plus prudent).
function decision(note, offre, refus, sens) {
  if (sens && sens.sensible) return "humain";
  const o = offre && typeof offre === "object" ? offre : {};
  if (!(refus || []).length && Number(note) >= 4 && o.avis_auto === true) return "publication_automatique";
  return o.avis_equipe === true || o.delegation === true ? "equipe" : "validation_commercant";
}
// Consigne de langue ajoutee a la consigne de redaction (n8n, « Triage et prompt ») pour un commerce neerlandophone. Francais (et anglais) : inchange.
const CONSIGNE_NL = "## Langue de la réponse\nLe commerce est néerlandophone (fiche.langue = « nl ») : écris la réponse en néerlandais de Belgique, naturel et professionnel, "
  + "en vouvoyant avec « u » et « uw » (jamais « je », « jij », « jouw »), même si l'avis est écrit dans une autre langue. Salutation : « Dag » ou « Beste » suivi du prénom, "
  + "jamais « Geachte », « Meneer » ni « Mevrouw ». Les règles ci-dessus s'appliquent telles quelles (en néerlandais : pas de « huisgemaakt », « vers », « ambachtelijk », "
  + "« lokaal » ni prix sans la fiche ; avis négatif : « Het spijt ons », « Jammer dat » ; aucune promesse comme « voortaan » ou « nooit meer »).";
// Lot 8 : réponse dans la langue de l'avis s'il est écrit en français, néerlandais ou anglais ; sinon dans la langue du commerce.
const CONSIGNE_EN = "## Langue de la réponse\nL'avis est écrit en anglais : réponds en anglais, chaleureux et poli, sans « Dear Sir/Madam », avec les mêmes règles "
  + "(rien d'inventé, aucun geste ni promesse comme « from now on » ou « never again », aucune action que le commerçant n'a pas confirmée).";
function consigneLangue(fiche, avis) {
  const la = avis && avis.texte ? langueTexte(avis.texte) : null;
  if (la === "en") return "\n\n" + CONSIGNE_EN;
  if (la === "nl" || (!la && fiche && fiche.langue === "nl")) return "\n\n" + CONSIGNE_NL;
  return "";
}
const CONSIGNE = "# Consigne de rédaction : réponse à un avis Google\n\nTu rédiges la réponse d'un commerce à un avis Google. Tu reçois : la note, le prénom affiché de l'auteur, le texte de l'avis, et la fiche du commerce (nom, ville, ton, spécialités, mots-clés, mentions autorisées, contact, gestes commerciaux prévus). Tu ne connais RIEN d'autre sur le commerce.\n\n## Méthode (formation E-réputation IA, module 4)\n- Le moteur te donne le prénom quand le nom affiché en est un ; sinon il te donne « aucun ». Avec un prénom : adresse-toi à la personne par ce prénom, en vouvoyant. Avec « aucun » : commence par « Bonjour, » ou par un remerciement, sans nom. Jamais « Cher », « Monsieur », « Madame », jamais de nom de famille.\n- Si l'avis n'a pas de texte : une ou deux phrases, sans aucun détail sur la visite (tu ne sais rien), en variant la tournure.\n- Réponse concise, directement liée au contenu de l'avis : reprends un détail réel de l'avis.\n- Donne envie à un futur lecteur de venir, sans en faire trop.\n- N'ajoute aucun mot-clé ni nom de ville. Tu peux reprendre le plat ou le service que le client a lui-même nommé, avec ses mots.\n- 1 ou 2 étoiles : reconnais ce que la personne a vécu (désolés, nous regrettons), sans te défendre, sans contester, sans t'excuser d'une faute que tu ne connais pas. Pour 1 étoile, invite-la à joindre directement le commerce en donnant le contact de la fiche tel qu'il est écrit ; si la fiche n'a pas de contact, invite-la à en reparler avec l'équipe sur place. Pour 2 étoiles, ne donne le contact que si l'avis décrit un vrai problème (réservation, facture, comportement, attente très longue) : pour un plat tiède, un numéro est disproportionné.\n- 3 étoiles : commence par ce qui a plu, puis reconnais le point faible en une phrase (« dommage », « nous le regrettons »). Ne donne le contact que si l'avis décrit un vrai problème (réservation, facture, comportement, attente très longue).\n- 4 et 5 étoiles : jamais de numéro ni de contact. N'écris jamais « en privé », « message privé », « MP » ni « écrivez-nous » sans coordonnées : Google ne permet pas d'écrire en privé à l'auteur d'un avis.\n- Ton poli et professionnel, jamais défensif ni désinvolte. Termine sur une note positive qui invite à revenir.\n- 5 étoiles : une à trois phrases. 4 et 3 étoiles : deux à quatre phrases. 1 et 2 étoiles : trois à cinq phrases. 650 signes au plus.\n- Termine par la signature donnée par la fiche (champ signature, par exemple « Marco, Bistrot Orsane ») si elle existe, seule sur la fin, sans « Cordialement ».\n\n## Règles de vérité (contrôlées automatiquement, la réponse est refusée sinon)\n- Rien d'inventé sur le commerce : aucun produit, horaire, prix, origine ni promesse que la fiche ne contient pas. Ne reprends pas à ton compte une qualité citée par le client (« fait maison », « frais », « bio », « artisanal », « local ») : remercie sans la confirmer, sauf si la fiche l'autorise.\n- Aucun geste commercial (remboursement, remise, repas offert) sauf s'il est prévu dans la fiche.\n- Aucune promesse (« plus jamais », « désormais », « nous garantissons »).\n- Aucune action affirmée : n'écris jamais que le commerce a fait, changé, revu, transmis ou parlé de quelque chose (« nous en parlons en cuisine », « nous avons revu l'organisation »), sauf si la précision du commerçant le dit. Tu peux écrire que la remarque est « bien notée ».\n- Aucune donnée personnelle, aucun numéro ni adresse email autre que le contact de la fiche.\n- Aucune mention que le texte est écrit par une machine ni le contraire.\n- Aucun tiret double ni tiret long.\n- Tu reçois les dix dernières réponses du commerce. Ne reprends ni leur première phrase, ni leur dernière phrase, ni leurs formules (« merci d'avoir pris le temps », « nous espérons vous revoir bientôt », « à très bientôt »).\n\n## Avis jamais traités par toi\nSi l'avis évoque la santé, l'hygiène (cheveu, insecte, rongeur, saleté, viande pas cuite ou avariée), une allergie, un accident, une accusation grave (racisme, discrimination, vol, arnaque, harcèlement, violence), une menace (juridique, inspection, média), réponds exactement `HUMAIN` et rien d'autre : le commerçant reçoit la réponse de l'équipe sur WhatsApp et rien n'est publié sans son OK écrit.\n\n## Sortie\nUniquement le texte de la réponse, sans guillemets ni commentaire.\n";
const REECRITURE = "\n\n## Réécriture après le message du commerçant\nLe commerçant a lu l'avis et la réponse proposée, et nous a écrit le message ci-dessous. Réécris la réponse en tenant compte de ce qu'il dit (faits, précisions, ton), sans recopier son message tel quel et sans rien inventer de plus. Toutes les règles ci-dessus s'appliquent. S'il a écrit plusieurs messages, tiens compte de tous ; s'ils se contredisent, le dernier l'emporte. Pour un avis sensible, n'écris pas « HUMAIN » : écris une réponse prudente (aucune faute reconnue, aucun détail médical ou juridique, aucune promesse), qui sera relue par l'équipe. Si son message ne donne rien d'utilisable pour la réponse (question, demande de rappel, sujet sans rapport, refus de répondre), réponds exactement HUMAIN et rien d'autre.";

// L'avis vient du webhook (ligne de la base) ; la fiche, de la requête « Fiche du commerce ». Aucune donnée de contact du commerçant n'est envoyée.
const av = $('Webhook (base de données Supabase)').first().json.body.record;
const fiche = ficheAvecMarque($input.first().json[0] || $input.first().json);
const texte = av.texte || '', prenom = prenomDe(av.auteur || '');
const systeme = CONSIGNE + consigneLangue(fiche, {texte}) + "\n\n" + consigneMarque(fiche.marque, fiche.ton) + REECRITURE;
const recentes = (Array.isArray(fiche.recentes) ? fiche.recentes : []).map(x => x && x.reponse).filter(Boolean).reverse();
const ficheIA = {nom: fiche.nom, ville: fiche.ville, metier: fiche.metier, ton: fiche.ton, specialites: fiche.specialites, mentions_autorisees: fiche.mentions_autorisees,
  contact: fiche.contact, gestes: fiche.gestes, signature: fiche.signature, langue: fiche.langue};
// Revue du 17/11/2026 (point 4) : TOUS les messages du commerçant sur cet avis, dans l'ordre ; le dernier l'emporte s'ils se contredisent.
const msgs = (Array.isArray(av.corrections) && av.corrections.length ? av.corrections : [{texte: av.version_client || ''}]).map(x => x && x.texte).filter(Boolean);
const message = 'Note : ' + av.note + '\nPrénom affiché : ' + (prenom || 'aucun') + '\nAvis : ' + texte + '\nRéponse proposée : ' + (av.reponse_proposee || 'aucune')
  + '\nMessages du commerçant, dans l\'ordre (le dernier l\'emporte) :\n' + msgs.map((t, i) => (i + 1) + '. ' + t).join('\n') + '\nFiche du commerce : ' + JSON.stringify(ficheIA)
